// Plus Jakarta Sans (OFL), regular 400 to extra-bold 800, as @font-face rules for the PDF templates.
// Static files from @expo-google-fonts/plus-jakarta-sans, cut down to Latin / Latin-extended / punctuation / currency
// (same font version and glyph widths as the variable font the templates used to load from Google Fonts).
// Embedded so the PDF no longer needs the network while printing and the print engine embeds real TrueType fonts
// instead of Type 3 fonts.
export const plusJakartaSansFontCss = "@font-face{font-family:'Plus Jakarta Sans';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Plus Jakarta Sans';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Plus Jakarta Sans';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Plus Jakarta Sans';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Plus Jakarta Sans';font-style:normal;font-weight:800;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}";
